with RecursiveConnexions AS (
    select pl.PostId, pl.RelatedPostId, 1 as depth
      from PostLinks pl
    where pl.PostId in (select Id from Posts order by viewcount desc limit 100)
    union all
    select rc.RelatedPostId as PostId, pl.RelatedPostId, rc.depth+1
      from RecursiveConnexions rc
      join PostLinks pl
        on pl.PostId = rc.RelatedPostId layer.reverseCascade-polyoney(global decrement shuts()
